#!/usr/bin/env python3
from pathlib import Path
import re,sys
# OBELIA-01/02/03 only. OBELIA-01A/01B and polymorphism are protected.

def F(pid,title,aria,body,legend):
 return f'''<figure class="sys-fig v188-pencil-plate v188-obelia-remediation" data-v188-plate="{pid}"><figcaption><strong>{title}</strong><span class="ta-explain" lang="ta">TERMINOLOGY REVIEW PENDING</span></figcaption><svg class="sys-svg" viewBox="0 0 760 470" role="img" aria-label="{aria}" xmlns="http://www.w3.org/2000/svg"><rect width="760" height="470" fill="#fffefa"/><g fill="none" stroke="#303030" stroke-linecap="round" stroke-linejoin="round">{body}</g></svg><div class="v188-figure-legend" data-legend-en="{legend}" data-legend-ta="TERMINOLOGY REVIEW PENDING"></div></figure>'''
COL=F('OBELIA-01-R1','Obelia — colony architecture','Obelia colony showing hydrorhiza, hydrocaulus, feeding and reproductive zooids, outer perisarc and inner living coenosarc.',r'''<path d="M380 410V85M380 335Q290 300 245 210M380 275Q475 250 520 165M380 210Q305 175 275 110" stroke-width="6"/><path d="M380 410Q285 430 190 410M380 410Q475 430 570 410" stroke-width="7"/><path d="M245 210q-38-32-60 0q22 38 60 0ZM275 110q-38-32-60 0q22 38 60 0Z" stroke-width="2.4"/><path d="M485 250q42-55 78 0v85q-38 38-78 0Z" stroke-width="2.4"/><path d="M365 395V95M365 325Q285 292 238 220M395 395V95M395 325Q300 305 255 225" stroke-width="1.2"/><g stroke-width="1"><path d="M380 410L620 410"/><path d="M380 300L620 300"/><path d="M245 210L65 185"/><path d="M525 260L650 235"/><path d="M395 345L650 350"/><path d="M365 345L120 350"/></g><g fill="#222" stroke="none" font-family="sans-serif" font-size="13"><text x="630" y="415">Hydrorhiza</text><text x="630" y="305">Hydrocaulus</text><text x="10" y="180">Feeding zooid / hydranth</text><text x="600" y="225">Reproductive zooid / gonangium</text><text x="655" y="355">Perisarc — outer non-living sheath</text><text x="10" y="355">Coenosarc — inner living tissue</text></g>''','Hydrorhiza; hydrocaulus; feeding hydranths; reproductive gonangia; perisarc is the outer non-living protective sheath; coenosarc is the internal living tissue continuous through the colony')
MED=F('OBELIA-02-R1','Obelia — medusa anatomy','Obelia medusa showing umbrella, velum, radial canals, ring canal, gonads, dependent manubrium with terminal mouth and marginal tentacles.',r'''<path d="M180 230Q380 35 580 230Q380 285 180 230Z" stroke-width="3.2"/><path d="M205 228Q380 258 555 228" stroke-width="2"/><path d="M230 230Q250 250 270 232M490 232Q510 250 530 230" stroke-width="2"/><path d="M380 145V300" stroke-width="3"/><circle cx="380" cy="305" r="7"/><path d="M380 180H250M380 180H510M380 180L300 105M380 180L460 105" stroke-width="2"/><ellipse cx="300" cy="150" rx="20" ry="9"/><ellipse cx="460" cy="150" rx="20" ry="9"/><path d="M200 230q-15 80 0 145M240 240q-12 75 0 135M520 240q12 75 0 135M560 230q15 80 0 145" stroke-width="1.7"/><g stroke-width="1"><path d="M320 80L110 55"/><path d="M230 238L80 260"/><path d="M380 305L620 305"/><path d="M250 180L75 145"/><path d="M300 150L120 105"/></g><g fill="#222" stroke="none" font-family="sans-serif" font-size="13"><text x="10" y="50">Umbrella / bell</text><text x="10" y="280">Velum — inward marginal shelf</text><text x="625" y="310">Manubrium → terminal mouth</text><text x="10" y="140">Radial canals → marginal ring canal</text><text x="15" y="100">Gonads</text><text x="300" y="425">Marginal tentacles</text></g>''','Umbrella; velum; gonads; radial canals; ring canal; dependent central manubrium; terminal mouth; marginal tentacles')
LIFE=F('OBELIA-03-R1','Obelia — metagenetic life cycle','Obelia life cycle showing diploid colony, diploid male and female medusae, haploid gametes, fertilisation, diploid zygote, ciliated planula, settlement and new colony.',r'''<defs><marker id="oA" markerWidth="8" markerHeight="8" refX="7" refY="3" orient="auto"><path d="M0 0L8 3L0 6Z" fill="#303030" stroke="none"/></marker></defs><g stroke-width="2"><path d="M85 185V85m0 45l-35-25m35 25l35-25"/><path d="M220 90q40-45 80 0q-40 30-80 0ZM220 175q40-45 80 0q-40 30-80 0Z"/><circle cx="385" cy="90" r="12"/><circle cx="385" cy="175" r="12"/><circle cx="490" cy="135" r="22"/><path d="M575 115q45-30 90 0q-45 35-90 0Z"/><path d="M620 250V335m0-45l-35-25m35 25l35-25"/></g><g stroke-width="1.8" marker-end="url(#oA)"><path d="M120 115L205 90"/><path d="M120 145L205 175"/><path d="M300 90L365 90"/><path d="M300 175L365 175"/><path d="M400 105L468 130"/><path d="M400 165L468 140"/><path d="M512 135L565 115"/><path d="M620 135L620 235"/><path d="M585 300L180 300"/><path d="M180 300L95 200"/></g><g fill="#222" stroke="none" font-family="sans-serif" font-size="12" text-anchor="middle"><text x="85" y="55">Polyp colony (2n)</text><text x="260" y="55">Male medusa (2n)</text><text x="260" y="215">Female medusa (2n)</text><text x="385" y="55">Sperm (n)</text><text x="385" y="215">Egg (n)</text><text x="490" y="95">Fertilisation → zygote (2n)</text><text x="620" y="85">Ciliated planula</text><text x="620" y="365">Settlement → new colony (2n)</text><text x="350" y="325">Asexual medusa production/release from colony; sexual medusae produce gametes</text></g>''','Colony (2n) produces/releases medusae (2n); male and female medusae produce gametes (n); fertilisation forms zygote (2n); zygote develops into ciliated planula; planula settles and develops into a new colony (2n)')

def replace(html,old,new):
 pat=rf'<figure[^>]*data-v188-plate="{re.escape(old)}"[\s\S]*?</figure>'
 out,n=re.subn(pat,new,html,count=1)
 if n!=1: raise SystemExit(f'expected one active {old}, found {n}')
 return out

def main(root):
 paths=[Path(root)/'academic_payload/index.html',Path(root)/'app/src/main/assets/www/index.html']
 for p in paths:
  s=p.read_text(encoding='utf-8'); s=replace(s,'obelia-colony',COL); s=replace(s,'obelia-medusa',MED); s=replace(s,'obelia-life-cycle',LIFE); p.write_text(s,encoding='utf-8')
 if paths[0].read_bytes()!=paths[1].read_bytes(): raise SystemExit('payload copies diverged')
 print('OBELIA remediation applied; protected zooid-detail candidate untouched; BUILD_ELIGIBLE=NO')
if __name__=='__main__': main(sys.argv[1] if len(sys.argv)>1 else '.')
